import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/BDM.scaBLLhv.js";import{_ as a,o as s,c as r,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"Stop sensor","description":"","frontmatter":{},"headers":[],"relativePath":"use/stopsensor.md","filePath":"use/stopsensor.md"}'),i={name:"use/stopsensor.md"};function p(l,e,c,d,h,m){return s(),r("div",null,[...e[0]||(e[0]=[n('<p>Stopping a sensor in xDrip has very different functions depending on the sensor itself.</p><h3 id="g6-and-1" tabindex="-1">G6 and 1 <a class="header-anchor" href="#g6-and-1" aria-label="Permalink to &quot;G6 and 1&quot;">​</a></h3><p>Reference documentation is <a href="https://navid200.github.io/xDrip/docs/Proper-connectivity.html" target="_blank" rel="noreferrer">here</a>.</p><h3 id="g7-and-1" tabindex="-1">G7 and 1+ <a class="header-anchor" href="#g7-and-1" aria-label="Permalink to &quot;G7 and 1+&quot;">​</a></h3><p>These sensors stop by themselves after 10 days and 12 hours. Some transmitters running alternate firmware report a longer 15 days and 12 hours lifetime instead; xDrip detects this automatically from the transmitter firmware; it isn&#39;t a setting you choose.</p><br><h3 id="libre" tabindex="-1">Libre <a class="header-anchor" href="#libre" aria-label="Permalink to &quot;Libre&quot;">​</a></h3><p>xDrip is not able to stop a Libre sensor, actually you can&#39;t stop this sensor: if it doesn&#39;t fail it will run its useful lifetime and stop by itself after 14 days and 12 hours.</p><p>xDrip sensor stop is only used to invalidate previous calibrations. This operation is necessary and recommended each time you replace your sensor.</p><br><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Stop Sensor</p></div><p>Confirm STOP SENSOR unless you only want to <a href="./../calibrate/calibrate.html#reset-all-calibrations">reset all calibrations</a>.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"> Stop Sensor <span class="symbol"></span></p><p> Only stop your sensor when you actually plan to remove it, otherwise leave it running!</p><p>       <span style="background-color:white;color:black;"> STOP SENSOR </span></p></div><p>Confirm you want to stop the sensor.</p><div class="admonition xdripitem"><p class="admonition-title">Are you sure?</p><p> Do you want to stop the sensor?</p><p>       NO    <span style="background-color:white;color:black;"> YES </span></p></div><p>If you change your mind and the sensor hasn&#39;t expired yet, you can always <a href="./startsensor.html#libre">&quot;restart&quot;</a> it: it will resume the current session and possibly ask for a new calibration. xDrip doesn&#39;t physically restart Libre sensors.</p><br><h3 id="followers-and-companion-apps" tabindex="-1">Followers and companion apps <a class="header-anchor" href="#followers-and-companion-apps" aria-label="Permalink to &quot;Followers and companion apps&quot;">​</a></h3><p>There is no point in stopping a sensor when using a follower app.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>The only exception is <a href="./sync.html#accept-followers-actions">xDrip Sync follower that might transmit the Start or Stop command to the actual sensor if it is directly connected to xDrip acting as master</a>.<br> Do not use Start and Stop sensor with xDrip Sync follower unless you know the person with the master xDrip phone will know what to do with a stopped sensor!</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.03" target="_blank" rel="noreferrer"><em>Last modified 6/7/2026</em></a></p>',22)])])}const w=a(i,[["render",p]]);export{b as __pageData,w as default};
